/bin/bash -lc "nl -ba /tmp/sef-alloc/Finish.v | sed -n '170,202p'
python3 - <<'PY'
p='/tmp/sef-alloc/Finish.v';s=open(p).read();a=s.index('        all: intros z Hz;');b=s.index('Qed.',a)
s=s[:a]+r'''        all: intros z Hz; apply Hcurrent;
          simpl in Hz; repeat rewrite in_union in Hz;
          destruct Hz as [Hz | [Hz | Hz]];
          try contradiction (notin_empty Hz);
          rewrite in_union; left; rewrite in_union; left; exact Hz.
'''+s[b:];open(p,'w').write(s)
PY
bash /tmp/sef-alloc/check Finish"

